with UserReps as (
    select
        u.Id as UserId,
        u.DisplayName,
        u.Reputation,
        gs.GabtScore,
        ost.OutStandScore,
        bn.BadgeClasses,
        frq.FlagReasonCount,
        approaches.TopContributionCharBadge1AssignedAt
    from Users u
    left join (
        select
            p.OwnerUserId,
            count(*) BadgesOfClass1
        from Posts p
        inner join Badges b on b.UserId = p.OwnerUserId and b.Class = 1
        group by p.OwnerUserId
        having count(*) > 0
    ) aks on oks.OwnerUserId = u.Id
    left join (
        select usr.id "uas", sum(precAll.WPlusLocWin) Gb posicion,
                moviment/prooutput + cac.restinske weade xbo.tm

